-- =============================================================================
-- Localites — PROPOSED Stage 1 schema
-- =============================================================================
-- STATUS: PROPOSAL FOR REVIEW. NOT APPLIED TO ANY DATABASE.
--
-- Once approved, this becomes the first numbered migration. It is kept here so
-- the data model can be reviewed as real, checkable SQL rather than prose.
--
-- Conventions (see docs/B-domain-and-data-model.md §1):
--   * Primary keys are UUIDs, generated by the application as UUID v7.
--     gen_random_uuid() defaults exist only as a safety net.
--   * Statuses are text + CHECK constraints, not Postgres enums: adding a value
--     is a one-line, non-locking migration.
--   * Money is integer cents + ISO currency code.
--   * Timestamps are timestamptz (stored UTC).
--   * Nothing important is hard-deleted; relationships end with a timestamp.
--   * Stage 2+ tables are in stage2-3-proposed.sql (the consumer-vendor
--     handshake and reviews). Guest/RSVP tables are designed in doc B only.
-- =============================================================================

create extension if not exists citext;
create extension if not exists pg_trgm;
create extension if not exists postgis;

-- -----------------------------------------------------------------------------
-- Shared helpers
-- -----------------------------------------------------------------------------

create function set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- A slug is lowercase words separated by single hyphens.
create domain slug_text as citext
  check (value ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(value) <= 80);

-- =============================================================================
-- IDENTITY
-- =============================================================================

-- One row per person with an account. id equals the auth provider's user id.
create table app_user (
  id            uuid primary key,
  display_name  text not null check (char_length(display_name) between 1 and 120),
  email         citext not null unique,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  deleted_at    timestamptz            -- set when personal data has been erased
);
create trigger app_user_updated before update on app_user
  for each row execute function set_updated_at();

-- Platform team roles. Checked server-side for every admin action.
create table platform_role (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references app_user(id),
  role        text not null check (role in ('admin')),
  granted_by  uuid references app_user(id),
  granted_at  timestamptz not null default now(),
  revoked_at  timestamptz
);
create unique index platform_role_active
  on platform_role (user_id, role) where revoked_at is null;

-- =============================================================================
-- PLACE & TAXONOMY  (reference data managed by admins, not hardcoded)
-- =============================================================================

create table municipality (
  id          uuid primary key default gen_random_uuid(),
  slug        slug_text not null unique,
  name        text not null,
  region      text not null,                       -- e.g. 'Simcoe County'
  province    char(2) not null default 'ON',
  centroid    geography(point, 4326),              -- from an authoritative source; never guessed
  is_active   boolean not null default false,      -- only active places appear in filters
  sort_order  int not null default 0
);

create table category (
  id           uuid primary key default gen_random_uuid(),
  parent_id    uuid references category(id),
  slug         slug_text not null unique,
  name         text not null check (char_length(name) between 1 and 80),
  description  text,
  sort_order   int not null default 0,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  check (parent_id is distinct from id)
);
create index category_parent on category (parent_id);

-- Tier 2 metadata: the registry of filterable, typed vendor attributes.
create table attribute_definition (
  id             uuid primary key default gen_random_uuid(),
  key            text not null unique check (key ~ '^[a-z][a-z0-9_]{1,62}$'),
  label          text not null,
  help_text      text,
  data_type      text not null
                 check (data_type in ('boolean', 'number', 'single_choice', 'multi_choice', 'text')),
  unit           text,                              -- e.g. 'guests', 'km'
  is_filterable  boolean not null default false,
  is_public      boolean not null default true,
  is_active      boolean not null default true,
  sort_order     int not null default 0,
  -- Free text is never a filter: it can't be filtered consistently.
  check (not (data_type = 'text' and is_filterable))
);

create table attribute_option (
  id                       uuid primary key default gen_random_uuid(),
  attribute_definition_id  uuid not null references attribute_definition(id),
  value                    text not null check (value ~ '^[a-z0-9_]+$'),
  label                    text not null,
  sort_order               int not null default 0,
  is_active                boolean not null default true,
  unique (attribute_definition_id, value)
);

-- Which attributes apply to which categories (e.g. max_guests -> party venues).
create table attribute_definition_category (
  attribute_definition_id  uuid not null references attribute_definition(id),
  category_id              uuid not null references category(id),
  primary key (attribute_definition_id, category_id)
);

-- =============================================================================
-- MEDIA
-- =============================================================================

create table media_asset (
  id            uuid primary key default gen_random_uuid(),
  owner_kind    text not null check (owner_kind in ('vendor', 'platform', 'user')),
  owner_id      uuid,                               -- null only for owner_kind = 'platform'
  bucket        text not null check (bucket in ('public', 'private')),
  storage_path  text not null unique,
  mime_type     text not null check (mime_type in ('image/jpeg', 'image/png', 'image/webp', 'application/pdf')),
  byte_size     int not null check (byte_size > 0 and byte_size <= 10485760),
  width         int,
  height        int,
  alt_text      text,
  uploaded_by   uuid references app_user(id),
  created_at    timestamptz not null default now(),
  deleted_at    timestamptz,
  check ((owner_kind = 'platform') = (owner_id is null))
);

-- =============================================================================
-- VENDORS  (the canonical business record — one per business, forever)
-- =============================================================================

create table vendor (
  id                       uuid primary key default gen_random_uuid(),
  slug                     slug_text not null unique,
  display_name             text not null check (char_length(display_name) between 1 and 160),
  tagline                  text check (char_length(tagline) <= 160),
  description              text check (char_length(description) <= 5000),
  primary_municipality_id  uuid not null references municipality(id),

  -- Contact the vendor has published or provided (see decisions D-03/D-04).
  -- Messaging on Localites is available once the listing is claimed (see D-05).
  website_url              text check (website_url ~ '^https?://'),
  public_email             citext,
  public_phone             text check (public_phone ~ '^\+?[0-9 ().-]{7,20}$'),

  -- Lifecycle (transitions enforced in application code, ADR-017).
  listing_status           text not null default 'draft'
                           check (listing_status in ('draft', 'pending_review', 'published', 'unpublished', 'archived')),
  claim_status             text not null default 'unclaimed'
                           check (claim_status in ('unclaimed', 'claim_pending', 'claimed')),
  verification_status      text not null default 'unverified'
                           check (verification_status in ('unverified', 'verified', 'lapsed')),
  verified_at              timestamptz,
  source                   text not null check (source in ('admin_entered', 'vendor_submitted')),

  -- Tier 3: display-only extras. Never filtered on. Guarded by trigger below.
  profile_extras           jsonb not null default '{}'::jsonb
                           check (jsonb_typeof(profile_extras) = 'object'),

  search_document          tsvector generated always as (
                             setweight(to_tsvector('english', coalesce(display_name, '')), 'A') ||
                             setweight(to_tsvector('english', coalesce(tagline, '')), 'B') ||
                             setweight(to_tsvector('english', coalesce(description, '')), 'C')
                           ) stored,

  published_at             timestamptz,
  archived_at              timestamptz,
  created_by               uuid references app_user(id),
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),

  -- Honesty constraints: a status cannot exist without its supporting fact.
  check (verification_status = 'unverified' or verified_at is not null),
  check (listing_status <> 'published' or published_at is not null),
  check (listing_status <> 'archived' or archived_at is not null)
);
create trigger vendor_updated before update on vendor
  for each row execute function set_updated_at();
create index vendor_search on vendor using gin (search_document);
create index vendor_name_trgm on vendor using gin (display_name gin_trgm_ops);
create index vendor_status_place on vendor (listing_status, primary_municipality_id);

-- Old slugs keep redirecting after a business renames.
create table vendor_slug_history (
  slug        slug_text primary key,
  vendor_id   uuid not null references vendor(id),
  retired_at  timestamptz not null default now()
);

create table vendor_link (
  id          uuid primary key default gen_random_uuid(),
  vendor_id   uuid not null references vendor(id),
  kind        text not null check (kind in ('facebook', 'instagram', 'tiktok', 'youtube', 'other')),
  url         text not null check (url ~ '^https://'),
  sort_order  int not null default 0
);

-- Who can manage a vendor. Ending a membership keeps history.
create table vendor_member (
  id          uuid primary key default gen_random_uuid(),
  vendor_id   uuid not null references vendor(id),
  user_id     uuid not null references app_user(id),
  role        text not null check (role in ('owner', 'manager', 'staff')),
  added_by    uuid references app_user(id),
  created_at  timestamptz not null default now(),
  ended_at    timestamptz
);
create unique index vendor_member_active
  on vendor_member (vendor_id, user_id) where ended_at is null;
create index vendor_member_user on vendor_member (user_id) where ended_at is null;

create table vendor_category (
  vendor_id    uuid not null references vendor(id),
  category_id  uuid not null references category(id),
  is_primary   boolean not null default false,
  primary key (vendor_id, category_id)
);
create unique index vendor_category_one_primary
  on vendor_category (vendor_id) where is_primary;
create index vendor_category_by_category on vendor_category (category_id);

-- Services and packages. Pricing is optional and must be honest:
-- a priced model requires a price; 'on_request'/'not_listed' must not have one.
create table vendor_service (
  id                uuid primary key default gen_random_uuid(),
  vendor_id         uuid not null references vendor(id),
  name              text not null check (char_length(name) between 1 and 120),
  description       text check (char_length(description) <= 2000),
  pricing_model     text not null
                    check (pricing_model in ('fixed', 'starting_at', 'hourly', 'on_request', 'not_listed')),
  price_cents       int check (price_cents >= 0),
  currency          char(3) not null default 'CAD',
  price_note        text check (char_length(price_note) <= 200),
  duration_minutes  int check (duration_minutes > 0),
  min_guests        int check (min_guests > 0),
  max_guests        int check (max_guests > 0),
  is_active         boolean not null default true,
  sort_order        int not null default 0,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  check ((pricing_model in ('fixed', 'starting_at', 'hourly')) = (price_cents is not null)),
  check (min_guests is null or max_guests is null or min_guests <= max_guests)
);
create trigger vendor_service_updated before update on vendor_service
  for each row execute function set_updated_at();
create index vendor_service_vendor on vendor_service (vendor_id);

create table vendor_service_area (
  vendor_id        uuid not null references vendor(id),
  municipality_id  uuid not null references municipality(id),
  primary key (vendor_id, municipality_id)
);
create index vendor_service_area_by_place on vendor_service_area (municipality_id);

-- Tier 2 values. Exactly one value column is set, matching the definition's type.
create table vendor_attribute_value (
  id                       uuid primary key default gen_random_uuid(),
  vendor_id                uuid not null references vendor(id),
  attribute_definition_id  uuid not null references attribute_definition(id),
  option_id                uuid references attribute_option(id),
  value_boolean            boolean,
  value_number             numeric,
  value_text               text check (char_length(value_text) <= 500),
  check (num_nonnulls(option_id, value_boolean, value_number, value_text) = 1)
);
create unique index vendor_attr_scalar_once
  on vendor_attribute_value (vendor_id, attribute_definition_id) where option_id is null;
create unique index vendor_attr_option_once
  on vendor_attribute_value (vendor_id, attribute_definition_id, option_id) where option_id is not null;
create index vendor_attr_filter on vendor_attribute_value (attribute_definition_id, option_id);

create function enforce_attribute_value_type() returns trigger
language plpgsql as $$
declare
  def attribute_definition%rowtype;
begin
  select * into strict def from attribute_definition where id = new.attribute_definition_id;

  if def.data_type = 'boolean' and new.value_boolean is null then
    raise exception 'attribute "%" expects a yes/no value', def.key;
  elsif def.data_type = 'number' and new.value_number is null then
    raise exception 'attribute "%" expects a number', def.key;
  elsif def.data_type = 'text' and new.value_text is null then
    raise exception 'attribute "%" expects text', def.key;
  elsif def.data_type in ('single_choice', 'multi_choice') then
    if new.option_id is null then
      raise exception 'attribute "%" expects one of its listed options', def.key;
    end if;
    if not exists (select 1 from attribute_option o
                   where o.id = new.option_id and o.attribute_definition_id = def.id) then
      raise exception 'that option does not belong to attribute "%"', def.key;
    end if;
    if def.data_type = 'single_choice' and exists (
         select 1 from vendor_attribute_value v
         where v.vendor_id = new.vendor_id
           and v.attribute_definition_id = def.id
           and v.id <> new.id) then
      raise exception 'attribute "%" allows only one choice', def.key;
    end if;
  end if;
  return new;
end $$;

-- Known limitation: the single_choice check above can be raced by two concurrent
-- inserts for the same vendor+attribute. Acceptable for Stage 1 (listings are edited
-- by one person at a time); the application also serialises attribute saves per
-- vendor. Revisit if bulk import is introduced.
create trigger vendor_attribute_value_type
  before insert or update on vendor_attribute_value
  for each row execute function enforce_attribute_value_type();

-- Tier 3 guard: a key that is a managed attribute can't hide in profile_extras.
create function enforce_profile_extras_keys() returns trigger
language plpgsql as $$
declare
  clash text;
begin
  select d.key into clash
  from attribute_definition d
  where d.key in (select jsonb_object_keys(new.profile_extras))
  limit 1;
  if clash is not null then
    raise exception '"%" is a managed attribute; store it as an attribute value, not in profile_extras', clash;
  end if;
  return new;
end $$;

create trigger vendor_profile_extras_guard
  before insert or update of profile_extras on vendor
  for each row execute function enforce_profile_extras_keys();

create table vendor_media (
  vendor_id       uuid not null references vendor(id),
  media_asset_id  uuid not null references media_asset(id),
  role            text not null check (role in ('logo', 'cover', 'gallery')),
  sort_order      int not null default 0,
  primary key (vendor_id, media_asset_id)
);
create unique index vendor_media_one_logo  on vendor_media (vendor_id) where role = 'logo';
create unique index vendor_media_one_cover on vendor_media (vendor_id) where role = 'cover';

-- A request to take ownership of an (unclaimed) listing.
create table vendor_claim (
  id                uuid primary key default gen_random_uuid(),
  vendor_id         uuid not null references vendor(id),
  claimant_user_id  uuid not null references app_user(id),
  status            text not null default 'submitted'
                    check (status in ('submitted', 'approved', 'rejected', 'withdrawn')),
  claimant_note     text check (char_length(claimant_note) <= 2000),
  reviewed_by       uuid references app_user(id),
  reviewed_at       timestamptz,
  decision_note     text,
  created_at        timestamptz not null default now(),
  check ((status in ('approved', 'rejected')) = (reviewed_at is not null and reviewed_by is not null))
);
create unique index vendor_claim_one_open
  on vendor_claim (vendor_id, claimant_user_id) where status = 'submitted';

-- Verification is a recorded check with evidence, never just a badge.
create table verification_record (
  id                 uuid primary key default gen_random_uuid(),
  vendor_id          uuid not null references vendor(id),
  check_type         text not null
                     check (check_type in ('business_registration', 'insurance', 'identity', 'police_check', 'food_handler', 'other')),
  outcome            text not null check (outcome in ('passed', 'failed', 'inconclusive')),
  evidence_media_id  uuid references media_asset(id),     -- private bucket only
  notes              text,
  checked_by         uuid not null references app_user(id),
  checked_at         timestamptz not null default now(),
  expires_at         timestamptz
);
create index verification_record_vendor on verification_record (vendor_id, checked_at desc);

-- =============================================================================
-- DISCOVERY
-- =============================================================================

create table collection (
  id            uuid primary key default gen_random_uuid(),
  slug          slug_text not null unique,
  title         text not null,
  description   text,
  is_published  boolean not null default false,
  sort_order    int not null default 0,
  curated_by    uuid references app_user(id),
  created_at    timestamptz not null default now()
);

create table collection_item (
  collection_id  uuid not null references collection(id),
  vendor_id      uuid not null references vendor(id),
  sort_order     int not null default 0,
  note           text check (char_length(note) <= 280),
  primary key (collection_id, vendor_id)
);

-- Favourites. Created in Stage 1 or Stage 2 depending on decision D-02.
create table saved_vendor (
  user_id     uuid not null references app_user(id),
  vendor_id   uuid not null references vendor(id),
  created_at  timestamptz not null default now(),
  primary key (user_id, vendor_id)
);

-- =============================================================================
-- AUDIT  (append-only)
-- =============================================================================

create table status_change (
  id             uuid primary key default gen_random_uuid(),
  subject_type   text not null,          -- 'vendor', 'vendor_claim', later 'event_vendor', 'conversation', 'review', ...
  subject_id     uuid not null,
  field          text not null,          -- e.g. 'listing_status'
  from_status    text,
  to_status      text not null,
  actor_user_id  uuid references app_user(id),
  actor_kind     text not null check (actor_kind in ('consumer', 'vendor', 'admin', 'system')),
  reason         text,
  created_at     timestamptz not null default now()
);
create index status_change_subject on status_change (subject_type, subject_id, created_at);

create table audit_log (
  id             uuid primary key default gen_random_uuid(),
  actor_user_id  uuid references app_user(id),
  action         text not null,          -- e.g. 'vendor.publish', 'platform_role.grant'
  subject_type   text not null,
  subject_id     uuid,
  reason         text,
  changes        jsonb,                  -- before/after of changed fields
  session_ref    text,
  created_at     timestamptz not null default now()
);
create index audit_log_subject on audit_log (subject_type, subject_id, created_at);
create index audit_log_actor on audit_log (actor_user_id, created_at);

create function forbid_modification() returns trigger
language plpgsql as $$
begin
  raise exception '% is append-only', tg_table_name;
end $$;

create trigger status_change_append_only before update or delete on status_change
  for each row execute function forbid_modification();
create trigger audit_log_append_only before update or delete on audit_log
  for each row execute function forbid_modification();

-- =============================================================================
-- ANALYTICS  (first-party, minimal; created only if decision D-04 = A)
-- =============================================================================

create table analytics_event (
  id           bigint generated always as identity primary key,
  name         text not null check (name in ('vendor_contact_click', 'vendor_profile_view')),
  vendor_id    uuid references vendor(id),
  properties   jsonb not null default '{}'::jsonb check (jsonb_typeof(properties) = 'object'),
  occurred_at  timestamptz not null default now()
  -- Deliberately no user id, IP address, or device identifier.
);
create index analytics_event_vendor on analytics_event (vendor_id, name, occurred_at);

-- =============================================================================
-- ACCESS CONTROL  (second lock — see ADR-004)
-- =============================================================================
-- Row-level security is enabled on every table with NO policies for Supabase's
-- browser-facing roles (anon, authenticated). Those roles can read nothing.
-- The application connects as a restricted role, app_server.

do $$
declare t text;
begin
  foreach t in array array[
    'app_user', 'platform_role', 'municipality', 'category', 'attribute_definition',
    'attribute_option', 'attribute_definition_category', 'media_asset', 'vendor',
    'vendor_slug_history', 'vendor_link', 'vendor_member', 'vendor_category',
    'vendor_service', 'vendor_service_area', 'vendor_attribute_value', 'vendor_media',
    'vendor_claim', 'verification_record', 'collection', 'collection_item',
    'saved_vendor', 'status_change', 'audit_log', 'analytics_event'
  ] loop
    execute format('alter table %I enable row level security', t);
    execute format('alter table %I force row level security', t);
  end loop;
end $$;

-- The app role: read/write data, but no schema changes and no audit tampering.
-- (Created by the migration runner; password set out-of-band, never in git.)
--   create role app_server login;
--   grant usage on schema public to app_server;
--   grant select, insert, update on all tables in schema public to app_server;
--   revoke update, delete on status_change, audit_log from app_server;
--   grant usage on all sequences in schema public to app_server;
--   create policy app_server_all on <each table> to app_server using (true) with check (true);
-- Stage 2 replaces "using (true)" on guest/invitation/rsvp tables with
-- per-request ownership rules (see ADR-004).
